ValidationRule.errorConditionFormula:
AND(
  $Setup.Salesforce_Library_Settings__c.Disable_VRs__c = false,
  NOT( 
    CONTAINS($User.Username,$Label.UnicaIntegrationUserName) 
  ),
  NOT( 
   CONTAINS($User.Username,$Label.AdobeIntegrationUserName) 
  ),
  AND(
    RecordType.DeveloperName = 'MLCRM_Lead',
    NOT(
      ISBLANK(FinServ__RelatedAccount__c)
    ),
    FinServ__RelatedAccount__r.RecordType.DeveloperName <> 'PersonAccount'
  )
)
